<?php
/**
 * Self-contained Diskalkuli güncelleyici (tek dosya, dış dosya gerektirmez).
 * Yer: /home/diskalkuli/public_html/_dk.php
 * Çağrı: https://diskalkuli.com/_dk.php?go=1&secret=dk-update-2026-05-02-yilmaz-mutlu-sayfa-guncelleme
 * Çalıştıktan sonra dosyayı silin.
 */

$SECRET = "dk-update-2026-05-02-yilmaz-mutlu-sayfa-guncelleme";
if (!isset($_GET["go"]) || $_GET["go"] !== "1" || !isset($_GET["secret"]) || !hash_equals($SECRET, $_GET["secret"])) {
  http_response_code(403); die("Forbidden");
}

require "/home/diskalkuli/public_html/wp-load.php";

$admins = get_users(["role" => "administrator", "number" => 1]);
if (!empty($admins)) wp_set_current_user($admins[0]->ID);

header("Content-Type: text/plain; charset=utf-8");
echo "=== Diskalkuli güncelleme — " . date("Y-m-d H:i:s") . " ===

";

// Pages: slug => [base64_html, title]
$PAGES = [
  "anasayfa" => ["", ""],
  "diskalkuli-nedir" => ["", "Diskalkuli Nedir?"],
  "ebeveynler" => ["", "Ebeveynler"],
  "ogretmenler" => ["", "Öğretmenler"],
  "araclar" => ["", "DokunSay Araçları"],
  "hakkimizda" => ["", "Hakkımızda"],
  "yilmaz-mutlu" => ["", "Prof. Dr. Yılmaz Mutlu"],
];

// Anasayfa (slug yok)
$front_id = (int) get_option("page_on_front");
if ($front_id > 0 && isset($PAGES["anasayfa"])) {
  $html = base64_decode($PAGES["anasayfa"][0]);
  $r = wp_update_post(["ID" => $front_id, "post_content" => $html], true);
  echo "🏠 Anasayfa (ID $front_id): " . (is_wp_error($r) ? "❌ " . $r->get_error_message() : "✅") . "
";
  unset($PAGES["anasayfa"]);
}

// Diğer sayfalar
foreach ($PAGES as $slug => $info) {
  list($b64, $title) = $info;
  $html = base64_decode($b64);
  $page = get_page_by_path($slug);
  if ($page) {
    $r = wp_update_post(["ID" => $page->ID, "post_content" => $html], true);
    echo "📄 $slug (ID " . $page->ID . "): " . (is_wp_error($r) ? "❌ " . $r->get_error_message() : "✅") . "
";
  } else {
    $id = wp_insert_post(["post_title" => $title, "post_name" => $slug, "post_content" => $html, "post_status" => "publish", "post_type" => "page"], true);
    echo "➕ $slug yeni: " . (is_wp_error($id) ? "❌ " . $id->get_error_message() : "✅ ID " . $id) . "
";
  }
}

// Resim yükleme
$IMG_B64 = "";
$upload = wp_upload_dir();
$img_path = $upload["path"] . "/yilmaz-mutlu.jpg";
$img_url = $upload["url"] . "/yilmaz-mutlu.jpg";
file_put_contents($img_path, base64_decode($IMG_B64));
echo "
🖼  Resim: $img_path (" . filesize($img_path) . " bytes)
";

// Attachment
$existing = null;
$attachments = get_posts(["post_type" => "attachment", "name" => "yilmaz-mutlu", "posts_per_page" => 1]);
if (!empty($attachments)) $existing = $attachments[0];
if (!$existing) {
  $attach_id = wp_insert_attachment(["guid" => $img_url, "post_mime_type" => "image/jpeg", "post_title" => "Yılmaz Mutlu", "post_content" => "", "post_status" => "inherit", "post_name" => "yilmaz-mutlu"], $img_path);
  require_once ABSPATH . "wp-admin/includes/image.php";
  wp_update_attachment_metadata($attach_id, wp_generate_attachment_metadata($attach_id, $img_path));
  echo "   ✅ Attachment ID $attach_id
";
} else {
  $attach_id = $existing->ID;
  echo "   ℹ Attachment zaten var: ID $attach_id
";
}
$img_url = wp_get_attachment_url($attach_id);
echo "   🔗 $img_url
";

// Sayfa içerigindeki yer tutucu yolunu gerçek URL ile değiştir
$placeholder = "/wp-content/uploads/yilmaz-mutlu.jpg";
$real = str_replace(get_site_url(), "", $img_url);
if ($placeholder !== $real) {
  echo "
🔁 Yer tutucu değişimi: $placeholder → $real
";
  foreach (["hakkimizda", "yilmaz-mutlu"] as $s) {
    $p = get_page_by_path($s);
    if ($p && strpos($p->post_content, $placeholder) !== false) {
      wp_update_post(["ID" => $p->ID, "post_content" => str_replace($placeholder, $real, $p->post_content)]);
      echo "   ✅ $s
";
    }
  }
}

echo "
=== TAMAM. Bu dosyayı silin: " . __FILE__ . " ===
";
